/// <reference path="./sigApi.ApiBase.d.ts" />
/// <reference path="./sigApi.Color.d.ts" />

declare namespace SigApi {
    interface ApiColorManager extends ApiBase {
        /**
         * @param {string|number} colorPalette The identifier of the colorPalette
         * @param {string|number} color The identifier of the color
         * 
         * @returns {Color} The color object or null if no color was found
         */
        getColor(colorPalette: string | number, color: string | number): Color | null
        /**
         * converts a colorString of any color-format, to a rgba colorString
         * 
         * @param {string} string The color string
         *
         * @returns {string} The colorstring in rgba format
         */
        toRGBA(string: string): string
        /**
         * converts a colorString of any color-format, to a hex colorString
         * 
         * @param {string} string The color string
         *
         * @returns {string} The colorstring in hex
         */
        toHash(string: string): string
        /**
         * Function to check if parameter object is a instanceof Color.
         * This function can be used without importing the type Color to be used with the instanceof operator.
         * @param {*} object Any object to type check
         * @returns {boolean} Returns true if parameter object is instanceof Color, else false
         */
        instanceofColor(object: any): boolean
    }
}
